      "note": "Nhà ga cổ kính với đầu máy hơi nước, đứng chụp vài kiểu là đẹp."
    },
    {
      "poi_id": "p71",
      "kind": "meal",
      "must_do_id": null,
      "note": "Ngồi xuống ăn chậm rãi, không gian dễ chịu cho một người đi một mình."
    },
    {
      "poi_id": "p173",
      "kind": "activity",
      "must_do_id": null,
      "note": "Hồ rộng, thông reo quanh bờ, cứ thả bộ nhẹ nhàng là vừa."
    },
    {
      "poi_id": "p180",
      "kind": "activity",
      "must_do_id": null,
      "note": "Cỏ hồng phủ sườn đồi, lúc chiều xuống nhìn như tranh."
    },
    {
      "poi_id": "p33",
      "kind": "meal",
      "must_do_id": null,
      "note": "Góc nhỏ đậm chất địa phương, ngồi ăn tối nghe kể chuyện phố núi."
    }
  ]
}
```

