    },
    {
      "poi_id": "p157",
      "kind": "meal",
      "must_do_id": null,
      "note": "Nem nướng cuốn rau sống chấm tương béo, ăn xong còn muốn gọi thêm một dĩa."
    },
    {
      "poi_id": "p37",
      "kind": "activity",
      "must_do_id": null,
      "note": "Cà phê phin nhỏ giọt, ngồi nghe phố núi chậm rãi trôi qua ngoài cửa sổ."
    },
    {
      "poi_id": "p158",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bia thủ công mát lạnh, món nhắm tinh tế, tối ở Đà Lạt cứ thế mà thư thả."
    }
  ]
